INSERT IGNORE INTO posts
  (section, slug, status, origin, title, excerpt, tag, level, author, read_minutes, body, meta_description, focus_keyword, tags, featured, published_at, updated_at)
VALUES
('guias', 'como-escolher-o-dominio-do-site', 'published', 'manual', 'Como escolher o domínio do seu site sem se arrepender', 'Nome curto, extensão certa e registro no seu nome: o que considerar antes de registrar o endereço do site e os erros que custam caro depois.', NULL, 1, 'Equipe CriaSite', 4, '[{"type":"p","text":"O domínio é o endereço do seu site: é ele que vai no cartão de visita, na assinatura do e-mail e no QR code do balcão. Trocar de endereço depois significa refazer material impresso, perder links e recomeçar a reputação no Google. Este guia mostra como escolher o nome e a extensão, onde registrar e os erros que mais custam caro."},{"type":"h2","text":"O que é domínio (e o que não é)"},{"type":"p","text":"Domínio, hospedagem e site são coisas diferentes. O domínio é o nome que você aluga por um período, com renovação anual ou por vários anos. A hospedagem é o computador onde os arquivos do site ficam guardados. O DNS, uma espécie de catálogo de endereços da internet, liga um ao outro e diz onde o site está. Dá para ter domínio sem site, por exemplo só para receber e-mails."},{"type":"h2","text":"Como escolher o nome"},{"type":"ul","items":["Curto: quanto menos letras, menos chance de erro de digitação.","Fácil de falar ao telefone e de escrever depois de ouvir. Faça o teste do ditado: diga o nome para alguém e peça que digite.","Sem hífen, sem número e sem grafias ambíguas, como s ou ç, x ou ch.","Com o nome da sua marca, em vez de um serviço genérico cheio de palavras. Um endereço como padariadaana.com.br dura mais do que um que tente encaixar tudo o que a padaria vende.","Livre também nas redes sociais que você pretende usar, para o seu nome ser o mesmo em todo lugar."]},{"type":"h2","text":"Qual extensão usar"},{"type":"p","text":"A extensão é o final do endereço. Para quem fala com o público no Brasil, o .com.br é o mais reconhecido e passa confiança local. O .br é administrado pelo [Registro.br](https://registro.br) e exige CPF ou CNPJ. Existem categorias para profissões, como .adv.br e .med.br, com regras próprias que você confere direto no Registro.br."},{"type":"p","text":"O .com serve a quem fala com público de outros países. Extensões novas, como .app, .site e .online, funcionam, mas muita gente digita .com.br por hábito e pode errar o caminho. O .app, por exemplo, só abre por HTTPS, ou seja, o site precisa ter certificado de segurança. Se o nome for a sua marca, vale registrar também as variações principais e apontá-las para o endereço oficial."},{"type":"h2","text":"Passo a passo para registrar"},{"type":"ol","items":["Liste de 5 a 10 opções de nome.","Faça o teste do ditado com duas ou três pessoas.","Pesquise a disponibilidade no Registro.br, se for .br, ou no registrador que preferir.","Pesquise o nome no Google e no INPI, o órgão de registro de marcas, para não esbarrar em marca registrada de outra empresa.","Registre no seu CPF ou CNPJ, com um e-mail seu que você lê todos os dias.","Ative a renovação automática ou anote a data de vencimento.","Guarde a senha em um gerenciador e ative a verificação em duas etapas na conta do registrador."]},{"type":"h2","text":"Quanto custa"},{"type":"p","text":"Um domínio .com.br costuma custar algumas dezenas de reais por ano. Extensões internacionais variam bastante, e o primeiro ano muitas vezes vem com desconto que não se repete na renovação. Alguns planos de hospedagem incluem o domínio no primeiro período: confira o preço de renovação antes de aceitar. Os preços mudam, então veja o valor atual no site do registrador."},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Registrar no CPF ou CNPJ de quem fez o site. Quem aparece como titular é o dono do domínio, e recuperar depois dá trabalho.","Deixar vencer. O site e o e-mail param de funcionar e, passado o prazo de espera, outra pessoa pode registrar o seu endereço.","Usar um e-mail de contato que ninguém lê, e assim perder os avisos de vencimento.","Escolher um nome difícil de soletrar, que obriga a explicar o endereço letra por letra.","Pagar caro por um domínio de revenda, chamado de premium, sem necessidade."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Posso trocar de domínio depois?"},{"type":"p","text":"Pode, mas é preciso redirecionar cada página antiga para a nova com um redirecionamento 301, e você perde parte do caminho andado no Google. Veja o que esse código significa na ferramenta de [status HTTP](/ferramentas/status-http)."},{"type":"h3","text":"Preciso ter empresa para registrar um .com.br?"},{"type":"p","text":"Não. O CPF serve para o .com.br. As categorias profissionais, como .adv.br, têm regras próprias."},{"type":"h3","text":"Domínio com acento funciona?"},{"type":"p","text":"O Registro.br aceita, mas registre também a versão sem acento, porque muita gente digita sem."},{"type":"h3","text":"O domínio inclui e-mail?"},{"type":"p","text":"Não. O domínio só aponta para os serviços. O e-mail vem da hospedagem ou de um serviço de e-mail à parte."},{"type":"p","text":"Com o domínio na mão, a próxima etapa é decidir onde o site vai ficar: leia [como escolher a hospedagem](/guias/como-escolher-a-hospedagem-do-site) e acompanhe o seu progresso na [trilha do site no ar](/trilha#dominio)."},{"type":"p","text":"Leia também: [Checklist para lançar o site: o que conferir antes e depois](/guias/checklist-de-lancamento-do-site)"}]', 'Veja como escolher o nome e a extensão do domínio, onde registrar, por que deixar no seu CPF ou CNPJ e os erros que custam caro depois.', 'como escolher domínio', '["Domínio","Iniciante","Registro.br"]', 0, UTC_TIMESTAMP() - INTERVAL 6 DAY - INTERVAL 270 MINUTE, NULL),
('guias', 'como-escolher-a-hospedagem-do-site', 'published', 'manual', 'Como escolher a hospedagem do site: tipos, custos e cuidados', 'Compartilhada, VPS, nuvem ou construtor de sites: o que cada tipo resolve, o que conferir no plano e como não ser pego de surpresa na renovação.', NULL, 1, 'Equipe CriaSite', 4, '[{"type":"p","text":"Hospedagem é o computador ligado 24 horas por dia onde os arquivos do seu site ficam guardados. A escolha certa depende do tipo de site que você vai ter, não do plano mais caro. Neste guia você vê as opções, o que conferir antes de contratar e como comparar o custo de verdade, incluindo a renovação."},{"type":"h2","text":"Os tipos de hospedagem"},{"type":"h3","text":"Compartilhada"},{"type":"p","text":"Vários sites dividem o mesmo servidor. Resolve bem site institucional, blog e portfólio: o painel já vem pronto e instalar o WordPress leva poucos cliques. É a porta de entrada mais comum."},{"type":"h3","text":"VPS e nuvem"},{"type":"p","text":"Você recebe recursos reservados e mais controle sobre o servidor. Em troca, exige conhecimento técnico ou um suporte que administre o servidor por você. Faz sentido para lojas com muito acesso e sistemas próprios."},{"type":"h3","text":"Construtor de sites"},{"type":"p","text":"Plataformas como Wix e similares vendem a hospedagem e o editor no mesmo pacote. É mais simples de começar, mas dá menos liberdade e costuma ser mais difícil de levar o site para outro lugar depois."},{"type":"h3","text":"WordPress gerenciado"},{"type":"p","text":"A empresa cuida das atualizações, do cache e da segurança do WordPress. Custa mais que a compartilhada e poupa trabalho de manutenção."},{"type":"h2","text":"O que conferir no plano"},{"type":"ul","items":["Certificado SSL gratuito incluído, que dá o cadeado e o HTTPS. O Let''s Encrypt é gratuito e muitas empresas instalam sozinhas.","E-mail com o seu domínio e quantas caixas o plano inclui.","Backup automático: quem faz, com que frequência, se cobra para restaurar.","Onde ficam os servidores. Perto do seu público, a resposta tende a ser mais rápida.","Suporte em português e por qual canal ele atende.","Limites de armazenamento, número de sites e tráfego.","Facilidade para sair: dá para exportar os arquivos e o banco de dados quando você quiser?"]},{"type":"h2","text":"Disponibilidade: quanto tempo o site fica no ar"},{"type":"p","text":"As empresas costumam prometer uma disponibilidade em porcentagem. Uma garantia de 99,9% ao mês ainda permite cerca de 43 minutos fora do ar, porque 0,1% de 30 dias dá esse tempo. Veja também o que a empresa oferece se descumprir a promessa. Para entender o que o navegador recebe quando o site falha, consulte os [códigos de status HTTP](/ferramentas/status-http), como o 500 e o 503."},{"type":"h2","text":"Quanto custa"},{"type":"p","text":"A hospedagem compartilhada de entrada costuma ficar em algumas dezenas de reais por mês. VPS e nuvem custam mais e variam com os recursos. É comum o primeiro período ter um desconto grande e a renovação vir pelo preço cheio, e o desconto maior costuma exigir pagar vários meses adiantados. Os preços mudam com frequência: compare o preço de renovação, não só o da vitrine."},{"type":"h2","text":"Passo a passo para contratar"},{"type":"ol","items":["Defina o tipo de site e o volume de visitas que você espera.","Escolha o tipo de hospedagem que combina com isso.","Compare duas ou três empresas usando a lista de itens acima.","Calcule o custo total de dois anos, já com a renovação.","Contrate no seu nome e com o seu e-mail.","Aponte o domínio para a hospedagem seguindo as instruções do painel. A mudança pode levar algumas horas para valer em todo lugar.","Ative o SSL e teste se o site abre com https."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Escolher só pelo preço do primeiro mês, sem olhar a renovação.","Contratar VPS sem saber administrar um servidor.","Deixar a conta no nome de quem faz o site, o que pode travar uma mudança no futuro.","Nunca testar o backup, e descobrir que ele não funciona só quando precisa.","Usar um e-mail gratuito genérico no cartão de visita, em vez de um e-mail com o seu domínio."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Posso trocar de hospedagem depois?"},{"type":"p","text":"Pode. O domínio é separado da hospedagem, e muitas empresas ajudam a migrar o site."},{"type":"h3","text":"Hospedagem grátis vale a pena?"},{"type":"p","text":"Serve para testes. Costuma ter anúncios, limites baixos e endereço sem domínio próprio, o que não passa credibilidade para um negócio."},{"type":"h3","text":"Domínio e hospedagem precisam ser da mesma empresa?"},{"type":"p","text":"Não. Na mesma empresa fica mais simples de gerenciar, mas não é obrigatório. Se quiser rever como escolher o endereço, leia o guia sobre [como escolher o domínio](/guias/como-escolher-o-dominio-do-site)."},{"type":"h3","text":"Preciso de VPS para começar?"},{"type":"p","text":"Para site institucional ou blog, em geral não. A compartilhada atende e custa menos."},{"type":"p","text":"Com o site hospedado, falta dar a cara dele: veja [cores, fonte e favicon](/guias/cores-fonte-e-favicon-do-site) e marque o que já fez na [trilha](/trilha#hospedagem)."},{"type":"p","text":"Leia também: [Site lento? As causas mais comuns e como resolver as imagens](/guias/site-lento-causas-e-como-otimizar-imagens)"}]', 'Compartilhada, VPS, nuvem ou construtor: entenda os tipos de hospedagem, o que conferir no plano e como evitar surpresas na renovação.', 'como escolher hospedagem de site', '["Hospedagem","Iniciante","SSL"]', 0, UTC_TIMESTAMP() - INTERVAL 5 DAY - INTERVAL 95 MINUTE, NULL),
('guias', 'cores-fonte-e-favicon-do-site', 'published', 'manual', 'Cores, fonte e favicon: a identidade visual do seu site', 'Duas cores, uma ou duas fontes e um favicon nos tamanhos certos já dão cara de marca ao site. Veja como escolher sem errar no contraste.', NULL, 1, 'Equipe CriaSite', 4, '[{"type":"p","text":"O visitante julga o seu site em poucos segundos, e boa parte dessa impressão vem da aparência. Poucas escolhas feitas com consistência valem mais do que muitos efeitos. Neste guia você define as cores, a fonte e o favicon, o ícone da aba, sem errar no contraste e sem depender de designer."},{"type":"h2","text":"Escolha poucas cores"},{"type":"p","text":"Uma cor principal, para a marca e os botões, uma cor de apoio e neutros para texto e fundo são suficientes. A proporção 60-30-10, com 60% de fundo, 30% de apoio e 10% de destaque, é uma regra prática, não uma lei. Se você já tem um logo, parta das cores dele. Usar a cor de destaque só no que é clicável ajuda o visitante a entender o que é botão."},{"type":"h2","text":"Consistência vale mais do que criatividade"},{"type":"p","text":"Defina uma vez e repita: o mesmo tamanho de título em todas as páginas, o mesmo estilo de botão, o mesmo espaçamento entre os blocos. O visitante não percebe cada escolha, mas percebe quando algo muda de uma página para outra e o site parece montado por pessoas diferentes. Se você usa WordPress ou um construtor de sites, configure cores e fontes nas opções globais do tema, em vez de ajustar bloco por bloco."},{"type":"h2","text":"Contraste: o texto precisa ser lido"},{"type":"p","text":"A WCAG, o conjunto de diretrizes de acessibilidade do W3C, pede no nível AA um contraste de pelo menos 4,5 para 1 em texto normal e 3 para 1 em texto grande. O nível AAA, mais exigente, pede 7 para 1 e 4,5 para 1. O erro mais comum é texto cinza-claro sobre fundo branco, que cansa a vista e some ao sol, na tela do celular. Confira as suas combinações na [ferramenta de contraste de cores](/ferramentas/contraste-cores), que calcula a razão e mostra como o texto fica. Para ir além, as [orientações do W3C sobre acessibilidade](https://www.w3.org/WAI/) explicam o tema com detalhe."},{"type":"h2","text":"Fontes"},{"type":"ul","items":["Use no máximo duas famílias: uma para títulos e outra para o texto, ou a mesma nas duas.","No celular, deixe o texto corrido com pelo menos 16 px.","Fontes do sistema não precisam ser baixadas e carregam mais rápido.","Se usar fontes da web, como o Google Fonts, carregue só os pesos que usa: cada peso é um arquivo a mais.","Evite fonte manuscrita em texto corrido, porque cansa a leitura."]},{"type":"h2","text":"Favicon"},{"type":"p","text":"O favicon é o ícone que aparece na aba do navegador, nos favoritos e no atalho do celular. Os tamanhos usuais são um arquivo favicon.ico com 16, 32 e 48 pixels, um PNG de 180 por 180 para o ícone da Apple e PNGs de 192 por 192 e 512 por 512 para o Android. Parta de uma imagem quadrada e simples, que funcione bem pequena: só o símbolo ou a inicial, não o logo inteiro com texto. O [gerador de favicon](/ferramentas/gerador-favicon) cria todos esses arquivos a partir de uma imagem e entrega o código HTML para colar no site. Teste também em uma aba escura: um símbolo escuro com fundo transparente pode sumir, e nesse caso vale gerar o favicon com um fundo de cor."},{"type":"h2","text":"Passo a passo"},{"type":"ol","items":["Defina a cor principal e a cor de apoio.","Teste texto sobre fundo, e texto sobre botão, no verificador de contraste.","Escolha a fonte, ou as fontes, e os tamanhos de título e de texto.","Anote tudo em um mini guia de estilo, com os códigos das cores, as fontes e os tamanhos.","Gere o favicon e cole o código no site.","Confira no celular, com o brilho da tela baixo."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Usar muitas cores sem função definida.","Colocar texto sobre foto sem uma camada escura por cima.","Escolher uma fonte fina e clara demais.","Fazer o favicon com o logo inteiro: a 16 pixels vira um borrão.","Mudar as cores de uma página para outra."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Preciso de logo para começar?"},{"type":"p","text":"Não. O nome do negócio escrito em uma boa fonte resolve no início. O logo pode vir depois."},{"type":"h3","text":"O modo escuro é obrigatório?"},{"type":"p","text":"Não. Se você oferecer, confira o contraste também nele."},{"type":"h3","text":"Por que o meu favicon não aparece?"},{"type":"p","text":"O navegador guarda o ícone antigo em cache. Abra o site em uma aba anônima e confira se o caminho do arquivo no código está certo. Como as fontes e as imagens também pesam no carregamento, veja o guia sobre [site lento](/guias/site-lento-causas-e-como-otimizar-imagens)."},{"type":"p","text":"Com o visual definido, o próximo passo é preparar o site para o Google: leia [SEO básico para aparecer no Google](/guias/seo-basico-para-aparecer-no-google) e marque a etapa na [trilha](/trilha#visual)."},{"type":"p","text":"Leia também: [Como escolher a hospedagem do site](/guias/como-escolher-a-hospedagem-do-site)"}]', 'Como escolher as cores e a fonte do site com bom contraste e criar o favicon nos tamanhos certos, com ferramentas grátis no navegador.', 'cores e fonte para site', '["Visual","Iniciante","Acessibilidade"]', 0, UTC_TIMESTAMP() - INTERVAL 4 DAY - INTERVAL 400 MINUTE, NULL),
('guias', 'seo-basico-para-aparecer-no-google', 'published', 'manual', 'SEO básico: como fazer o seu site aparecer no Google', 'Título e descrição de cada página, sitemap e Search Console: o básico de SEO que todo site pequeno precisa, sem truque e sem promessa de 1º lugar.', NULL, 1, 'Equipe CriaSite', 4, '[{"type":"p","text":"SEO é deixar claro para o Google do que cada página trata e facilitar que ele a encontre. Ninguém garante posição na busca, e quem garante está vendendo promessa. O que dá para fazer é o básico bem feito, que aumenta a chance de o seu site aparecer. Este guia reúne esse básico, em ordem, para um site pequeno."},{"type":"h2","text":"Como o Google encontra o seu site"},{"type":"p","text":"O processo tem três etapas. Primeiro o Google rastreia: um robô segue os links e lê o sitemap, a lista de páginas do site. Depois indexa, ou seja, guarda a página no seu banco. Por fim classifica, decidindo a ordem dos resultados para cada busca. Um site novo pode levar de dias a semanas para aparecer, e não existe prazo fixo."},{"type":"h2","text":"Título e descrição de cada página"},{"type":"p","text":"O título da página é o texto azul que aparece no resultado da busca. A meta description é o resumo logo abaixo. O Google corta o texto pelo espaço na tela: títulos de até uns 60 caracteres e descrições de até uns 155 costumam aparecer inteiros. Ele também pode reescrever os dois, mas um bom texto aumenta a chance de ele usar o seu. Cada página precisa ter os seus, sem repetir, e os mesmos dados definem a prévia do link no WhatsApp. Escreva e veja a prévia no [gerador de meta tags](/ferramentas/meta-tags) e confira o tamanho no [contador de caracteres](/ferramentas/contador-de-caracteres)."},{"type":"h2","text":"Conteúdo que responde à busca"},{"type":"ul","items":["Faça uma página por assunto ou serviço, em vez de misturar tudo em uma só.","Use as palavras que o cliente usa, como conserto de geladeira em Campinas, e não só termos técnicos da sua área.","Coloque um título principal por página e divida o texto com intertítulos.","Escreva texto próprio: conteúdo copiado de outros sites não ajuda."]},{"type":"h2","text":"O celular também conta"},{"type":"p","text":"O Google avalia a versão do celular do seu site e considera a experiência de uso, como a velocidade de carregamento. Teste a página no celular e veja se o texto é legível sem dar zoom, se os botões são fáceis de tocar e se nada se sobrepõe. Esses cuidados valem para quem visita e, de quebra, ajudam na busca."},{"type":"h2","text":"Links de outros sites"},{"type":"p","text":"Quando outros sites apontam para o seu, o Google entende que o seu conteúdo tem valor. O caminho seguro é ser citado por parceiros, fornecedores, associações, diretórios sérios do seu setor e pela imprensa local. Comprar links em massa fere as regras do Google e pode prejudicar o site."},{"type":"h2","text":"Sitemap e robots.txt"},{"type":"p","text":"O sitemap lista as páginas do site para o Google. O robots.txt diz o que os robôs não devem rastrear e aponta o endereço do sitemap. Um robots.txt mal configurado pode bloquear o site inteiro, por isso vale conferir. O [gerador de sitemap e robots.txt](/ferramentas/sitemap-robots) monta os dois arquivos a partir da lista das suas páginas."},{"type":"h2","text":"Passo a passo"},{"type":"ol","items":["Escreva o título e a descrição de cada página.","Confira o tamanho dos textos.","Gere e publique o sitemap.xml e o robots.txt na pasta principal do site.","Crie a conta no [Google Search Console](https://search.google.com/search-console) e verifique o domínio.","Envie o sitemap na seção Sitemaps.","Use a inspeção de URL para pedir a indexação da página inicial.","Se o negócio atende em um local físico, crie o Perfil da Empresa no Google com o mesmo nome, endereço e telefone do site."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Usar o mesmo título em todas as páginas, como Início ou Home.","Deixar marcada no WordPress a opção de pedir aos buscadores que não indexem o site, ligada durante a construção.","Encher o texto de palavra-chave repetida, o que atrapalha a leitura.","Comprar links ou um pacote de SEO com garantia de primeiro lugar.","Publicar páginas só com imagem e sem texto."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Quanto tempo leva para aparecer?"},{"type":"p","text":"Não há prazo. Acompanhe pelo Search Console quais páginas o Google já indexou."},{"type":"h3","text":"Preciso pagar para aparecer no Google?"},{"type":"p","text":"Não. O resultado orgânico, o que aparece sem anúncio, é gratuito. Anúncio é outra coisa e é pago."},{"type":"h3","text":"A meta keywords ajuda?"},{"type":"p","text":"O Google não usa a meta keywords. O tempo é melhor gasto no título, na descrição e no conteúdo."},{"type":"h3","text":"E o Bing?"},{"type":"p","text":"Tem o Bing Webmaster Tools, onde você envia o mesmo sitemap."},{"type":"p","text":"Ser encontrado é metade do caminho: o site também precisa abrir rápido. Leia [site lento: as causas e como resolver as imagens](/guias/site-lento-causas-e-como-otimizar-imagens) e marque a etapa na [trilha](/trilha#google)."},{"type":"p","text":"Leia também: [Checklist para lançar o site: o que conferir antes e depois](/guias/checklist-de-lancamento-do-site)"}]', 'O básico de SEO para sites pequenos: título e descrição de cada página, sitemap, Search Console e o que fazer para o Google encontrar você.', 'seo básico', '["SEO","Google","Search Console"]', 0, UTC_TIMESTAMP() - INTERVAL 3 DAY - INTERVAL 150 MINUTE, NULL),
('guias', 'site-lento-causas-e-como-otimizar-imagens', 'published', 'manual', 'Site lento? As causas mais comuns e como resolver as imagens', 'Imagens grandes demais estão entre as causas mais comuns de site lento no celular. Veja como medir, o que mais pesa e como corrigir sem perder qualidade.', NULL, 2, 'Equipe CriaSite', 4, '[{"type":"p","text":"Um site lento perde o visitante antes de mostrar qualquer coisa, principalmente no celular com sinal fraco. A boa notícia é que a causa mais comum, as imagens, também é a mais fácil de resolver. Neste guia você aprende a medir, descobre o que mais pesa e corrige as imagens passo a passo."},{"type":"h2","text":"Como medir antes de mexer"},{"type":"p","text":"Use o [PageSpeed Insights](https://pagespeed.web.dev) com o endereço da página e olhe a aba do celular. Os dados de usuários reais, quando existem, valem mais do que o teste de laboratório. O Google resume a experiência em três medidas, os Core Web Vitals: o LCP, que mede quando o maior elemento da tela termina de carregar e deve ficar em até 2,5 segundos; o INP, que mede a resposta a cliques e toques e deve ficar em até 200 milissegundos; e o CLS, que mede quanto a página pula enquanto carrega e deve ficar em até 0,1. Meça de novo depois de cada mudança, e teste mais de uma página: a inicial, uma de serviço e uma com muitas fotos."},{"type":"h2","text":"As causas mais comuns"},{"type":"ul","items":["Imagens pesadas ou maiores do que o espaço onde aparecem.","Muitos plugins e scripts, como chat, pop-up, rastreadores e carrosséis.","Fontes da web com muitos pesos.","Vídeo hospedado no próprio site, em vez de incorporado de uma plataforma de vídeo.","Hospedagem sobrecarregada ou muito longe do público.","Falta de cache, que obriga o servidor a montar a página do zero a cada visita."]},{"type":"h2","text":"Quando a hospedagem é o problema"},{"type":"p","text":"Se mesmo com as imagens corrigidas a página demora a começar a carregar, o problema pode estar no servidor. Sinais comuns são lentidão em horários de pico, erros 503 de vez em quando e uma primeira resposta demorada na página inicial. Converse com o suporte da hospedagem, pergunte sobre cache no servidor e, se fizer sentido, avalie um plano melhor. Antes de pagar mais, confirme que as imagens e os plugins já foram resolvidos."},{"type":"h2","text":"Imagens: tamanho, formato e peso"},{"type":"h3","text":"Largura certa"},{"type":"p","text":"Não suba uma foto de câmera com 4000 pixels de largura para um espaço de 800. Para telas de alta densidade, vale usar até cerca de duas vezes a largura exibida. A [tabela de tamanhos de imagem](/ferramentas/tamanhos-de-imagem) lista as medidas usuais para o site e para as redes."},{"type":"h3","text":"Formato"},{"type":"p","text":"O WebP costuma gerar arquivos menores do que JPG e PNG com qualidade parecida, e os navegadores atuais abrem. Use PNG para ícones e imagens com transparência ou texto, e JPG continua bom para fotos. Para trocar o formato, use o [conversor de imagem](/ferramentas/converter-imagem)."},{"type":"h3","text":"Compressão"},{"type":"p","text":"Uma qualidade entre 75 e 85 costuma ser imperceptível em fotos. O [compressor de imagem](/ferramentas/comprimir-imagem) reduz o peso e a largura sem enviar o arquivo para nenhum servidor: tudo acontece no seu navegador."},{"type":"h2","text":"Detalhes no código"},{"type":"p","text":"Para quem edita o HTML ou o tema: informar a largura e a altura de cada imagem evita que a página pule enquanto carrega, o que melhora o CLS. O carregamento preguiçoso, o atributo loading com o valor lazy, deve ir nas imagens abaixo da primeira tela, e nunca na imagem principal do topo. O atributo srcset permite servir tamanhos diferentes conforme a tela. No WordPress, muitos temas e plugins de otimização já cuidam de parte disso."},{"type":"h2","text":"Passo a passo"},{"type":"ol","items":["Meça a página inicial no celular.","Liste as cinco imagens mais pesadas.","Redimensione cada uma para a largura em que aparece.","Converta para WebP quando fizer sentido.","Comprima.","Substitua no site, mantendo o nome do arquivo ou atualizando o endereço.","Meça de novo.","Só então olhe plugins, fontes e hospedagem."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Comprimir a imagem mas manter a largura gigante.","Usar carregamento preguiçoso na imagem do topo, o que piora o LCP.","Colocar na página inicial um carrossel com cinco fotos enormes.","Trocar de hospedagem antes de resolver as imagens.","Avaliar a velocidade só pelo computador de casa, com internet rápida."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Tirar nota 100 no PageSpeed é obrigatório?"},{"type":"p","text":"Não. Os limites dos Core Web Vitals importam mais do que a nota."},{"type":"h3","text":"Comprimir estraga a foto?"},{"type":"p","text":"Com qualidade moderada, a diferença costuma não ser visível. Compare antes e depois de publicar."},{"type":"h3","text":"O AVIF é melhor do que o WebP?"},{"type":"p","text":"Costuma gerar arquivos ainda menores, mas nem toda ferramenta e plataforma aceita. O WebP é a escolha mais compatível."},{"type":"p","text":"Com o site leve, falta publicar com segurança: siga para o [checklist de lançamento](/guias/checklist-de-lancamento-do-site) e marque a etapa na [trilha](/trilha#velocidade)."},{"type":"p","text":"Leia também: [Como escolher a hospedagem do site](/guias/como-escolher-a-hospedagem-do-site)"}]', 'Descubra por que o seu site está lento, como medir no PageSpeed Insights e como comprimir e redimensionar imagens para carregar rápido no celular.', 'site lento', '["Velocidade","Imagens","Core Web Vitals"]', 0, UTC_TIMESTAMP() - INTERVAL 2 DAY - INTERVAL 320 MINUTE, NULL),
('guias', 'checklist-de-lancamento-do-site', 'published', 'manual', 'Checklist para lançar o site: o que conferir antes e depois', 'HTTPS, redirecionamentos, formulários, meta tags, sitemap e Search Console: a lista do que conferir antes de divulgar o site e na primeira semana no ar.', NULL, 2, 'Equipe CriaSite', 4, '[{"type":"p","text":"Lançar um site é mais do que subir os arquivos. Uma revisão de meia hora evita formulário quebrado, cadeado faltando e página escondida do Google. Use esta lista antes de divulgar o endereço e depois, na primeira semana no ar. Marque cada item e só depois avise os clientes e os amigos."},{"type":"h2","text":"Endereço e segurança"},{"type":"ul","items":["Todas as páginas abrem com https e mostram o cadeado.","O endereço com http leva ao https por um redirecionamento 301.","A versão com www e a sem www levam ao mesmo endereço: escolha uma delas.","Confira o código de cada redirecionamento na ferramenta de [status HTTP](/ferramentas/status-http): o 301 é permanente e o 302 é temporário.","A página de erro 404 é personalizada e tem um link para a página inicial."]},{"type":"h2","text":"Conteúdo e contato"},{"type":"ul","items":["Cada página tem título e descrição próprios. Monte e confira no [gerador de meta tags](/ferramentas/meta-tags).","Cole o link no WhatsApp e veja se a prévia aparece com título e imagem.","O formulário foi testado de ponta a ponta: a mensagem chega e não cai no spam.","O botão do WhatsApp abre a conversa com a mensagem pronta. Crie o endereço no [gerador de link do WhatsApp](/ferramentas/link-whatsapp).","Telefone e e-mail são clicáveis no celular.","Os textos foram revisados, os links funcionam e o favicon aparece.","As imagens têm texto alternativo, que ajuda leitores de tela e o Google."]},{"type":"h2","text":"Celular"},{"type":"ul","items":["Abra o site em pelo menos um Android e um iPhone, ou no modo de dispositivo do navegador.","O menu abre, os botões são grandes o bastante para o dedo e nada vaza para o lado da tela.","Teste com a conexão lenta ativada nas ferramentas do navegador, para ver como o site se comporta fora do wi-fi."]},{"type":"h2","text":"Google e privacidade"},{"type":"ul","items":["O robots.txt não bloqueia o site.","O sitemap está publicado e foi enviado no [Google Search Console](https://search.google.com/search-console).","Se quiser, cadastre o site também no Bing Webmaster Tools.","Se o site usa estatísticas ou anúncios que coletam dados, a política de privacidade e o aviso de cookies estão publicados, de acordo com a LGPD. Para casos específicos, consulte um profissional."]},{"type":"h2","text":"Garantias para o dia seguinte"},{"type":"ul","items":["Existe um backup recente e você já testou restaurá-lo.","A renovação do domínio e da hospedagem está automática.","As senhas estão em um gerenciador e o painel tem verificação em duas etapas.","O e-mail com o seu domínio está funcionando.","Uma pessoa de confiança tem acesso de emergência às contas do domínio e da hospedagem, para o caso de você ficar sem poder acessá-las."]},{"type":"h2","text":"Faça um ensaio geral antes de avisar"},{"type":"p","text":"Peça a alguém que nunca viu o site que cumpra três tarefas: encontrar o telefone, entender o que você oferece e pedir um orçamento. Observe sem ajudar. Onde a pessoa hesitar, o visitante de verdade também vai hesitar. Corrija o que apareceu e só então divulgue."},{"type":"h2","text":"Primeira semana no ar"},{"type":"ol","items":["Divulgue para os clientes atuais.","Troque o link na bio das redes sociais e na assinatura do e-mail.","Imprima um [QR code](/ferramentas/qr-code) para o balcão, o cardápio ou o cartão. Teste em dois celulares antes de imprimir em quantidade.","Atualize o Perfil da Empresa no Google com o endereço do site.","Acompanhe no Search Console as páginas indexadas e os erros.","Peça a duas ou três pessoas de fora que usem o site e anote onde elas travam."]},{"type":"h2","text":"Erros comuns"},{"type":"ul","items":["Divulgar antes de testar o formulário.","Esquecer ligado o bloqueio aos buscadores do período de construção.","Deixar publicada uma página de teste ou um texto de exemplo.","Imprimir um QR code que aponta para um endereço provisório.","Não ter ninguém olhando o e-mail de contato.","Esquecer de avisar quem já divulga o endereço antigo, que passa a dar erro."]},{"type":"h2","text":"Perguntas frequentes"},{"type":"h3","text":"Preciso lançar com tudo pronto?"},{"type":"p","text":"Não. É melhor entrar no ar com poucas páginas boas do que esperar a perfeição. Você melhora o resto depois."},{"type":"h3","text":"Por que o site não aparece no Google no dia seguinte?"},{"type":"p","text":"O rastreamento leva tempo. O guia sobre SEO básico, que fica na etapa Google da trilha, explica o que acelera e o que não depende de você."},{"type":"h3","text":"O QR code expira?"},{"type":"p","text":"O QR code estático não expira. O que pode parar de funcionar é o endereço para onde ele aponta."},{"type":"p","text":"Com tudo conferido, volte à [trilha do site no ar](/trilha) e marque as etapas que concluiu."},{"type":"p","text":"Leia também: [Como escolher o domínio do site](/guias/como-escolher-o-dominio-do-site)"}]', 'Checklist para publicar o site sem sustos: HTTPS, redirecionamentos, formulários, meta tags, sitemap, Search Console e o que fazer na 1ª semana.', 'checklist lançamento de site', '["Lançamento","Checklist","Search Console"]', 0, UTC_TIMESTAMP() - INTERVAL 1 DAY - INTERVAL 45 MINUTE, NULL);
